// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAdminAudit List the append-only administrator audit log
	// (GET /api/v1/admin/audit)
	ListAdminAudit(w http.ResponseWriter, r *http.Request, params ListAdminAuditParams)
	// ListAdminDeliveries List assembled-chain item deliveries for pickup-point staff
	// (GET /api/v1/admin/deliveries)
	ListAdminDeliveries(w http.ResponseWriter, r *http.Request, params ListAdminDeliveriesParams)
	// TransitionAdminDelivery Confirm pickup-point receipt, dispatch, or recipient hand-off
	// (POST /api/v1/admin/deliveries/{deliveryId}/transition)
	TransitionAdminDelivery(w http.ResponseWriter, r *http.Request, deliveryId int64)
	// GetAdminFunnelMetrics Get the current product funnel snapshot
	// (GET /api/v1/admin/metrics/funnel)
	GetAdminFunnelMetrics(w http.ResponseWriter, r *http.Request)
	// ListAdminReports List message reports in the moderation queue
	// (GET /api/v1/admin/reports)
	ListAdminReports(w http.ResponseWriter, r *http.Request, params ListAdminReportsParams)
	// GetAdminReport Get one report with the reported message and full chat context
	// (GET /api/v1/admin/reports/{reportId})
	GetAdminReport(w http.ResponseWriter, r *http.Request, reportId int64)
	// AssignReport Assign an open report to the current administrator
	// (POST /api/v1/admin/reports/{reportId}/assign)
	AssignReport(w http.ResponseWriter, r *http.Request, reportId int64)
	// DecideReport Resolve or reject an open report assigned to the current administrator
	// (POST /api/v1/admin/reports/{reportId}/decision)
	DecideReport(w http.ResponseWriter, r *http.Request, reportId int64)
	// ListBlocks List the current user's personal blacklist
	// (GET /api/v1/blocks)
	ListBlocks(w http.ResponseWriter, r *http.Request, params ListBlocksParams)
	// BlockUser Block another user
	// (POST /api/v1/blocks)
	BlockUser(w http.ResponseWriter, r *http.Request)
	// UnblockUser Remove a user from the personal blacklist
	// (DELETE /api/v1/blocks/{blockedUserId})
	UnblockUser(w http.ResponseWriter, r *http.Request, blockedUserId int64)
	// ListCategories List all available item categories
	// (GET /api/v1/categories)
	ListCategories(w http.ResponseWriter, r *http.Request)
	// ListChains List chains involving the current user
	// (GET /api/v1/chains)
	ListChains(w http.ResponseWriter, r *http.Request, params ListChainsParams)
	// CreateChain Create a pending exchange chain from a matching cycle
	// (POST /api/v1/chains)
	CreateChain(w http.ResponseWriter, r *http.Request)
	// GetChain Get a chain involving the current user
	// (GET /api/v1/chains/{chainId})
	GetChain(w http.ResponseWriter, r *http.Request, chainId int64)
	// ListChatMessages Read or wait for direct-thread messages
	// (GET /api/v1/chains/{chainId}/chat/{counterpartId}/messages)
	ListChatMessages(w http.ResponseWriter, r *http.Request, chainId int64, counterpartId int64, params ListChatMessagesParams)
	// SendChatMessage Send a direct message to a neighboring participant
	// (POST /api/v1/chains/{chainId}/chat/{counterpartId}/messages)
	SendChatMessage(w http.ResponseWriter, r *http.Request, chainId int64, counterpartId int64)
	// MarkChatThreadRead Mark direct-thread messages as read
	// (POST /api/v1/chains/{chainId}/chat/{counterpartId}/read)
	MarkChatThreadRead(w http.ResponseWriter, r *http.Request, chainId int64, counterpartId int64)
	// SubmitChainDecision Approve or decline participation in a chain
	// (POST /api/v1/chains/{chainId}/decision)
	SubmitChainDecision(w http.ResponseWriter, r *http.Request, chainId int64)
	// ConfirmChainReceipt Confirm receipt of the current participant's incoming item
	// (POST /api/v1/chains/{chainId}/receipt)
	ConfirmChainReceipt(w http.ResponseWriter, r *http.Request, chainId int64)
	// CreateChainReview Review a neighbour after a completed exchange
	// (POST /api/v1/chains/{chainId}/reviews)
	CreateChainReview(w http.ResponseWriter, r *http.Request, chainId int64)
	// ListChatThreads List all direct exchange-chain conversations
	// (GET /api/v1/chat/threads)
	ListChatThreads(w http.ResponseWriter, r *http.Request)
	// SubscribeEvents Subscribe to server-sent events
	// (GET /api/v1/events)
	SubscribeEvents(w http.ResponseWriter, r *http.Request)
	// GetHealth Check service readiness
	// (GET /api/v1/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListItems List the current user's exchange items
	// (GET /api/v1/items)
	ListItems(w http.ResponseWriter, r *http.Request, params ListItemsParams)
	// CreateItem Create an exchange item
	// (POST /api/v1/items)
	CreateItem(w http.ResponseWriter, r *http.Request)
	// GetItem Get an exchange item
	// (GET /api/v1/items/{itemId})
	GetItem(w http.ResponseWriter, r *http.Request, itemId int64)
	// UpdateItem Update an exchange item or withdraw it from matching
	// (PATCH /api/v1/items/{itemId})
	UpdateItem(w http.ResponseWriter, r *http.Request, itemId int64)
	// ResolveItemCategories Resolve categories that require the item owner's input
	// (POST /api/v1/items/{itemId}/category-decision)
	ResolveItemCategories(w http.ResponseWriter, r *http.Request, itemId int64)
	// FindMatchingCycles Find exchange cycles that contain the requested item
	// (GET /api/v1/items/{itemId}/matching)
	FindMatchingCycles(w http.ResponseWriter, r *http.Request, itemId int64)
	// UploadMedia Upload an image for a future exchange item
	// (POST /api/v1/media)
	UploadMedia(w http.ResponseWriter, r *http.Request)
	// GetMedia Read a stored image through the backend
	// (GET /api/v1/media/{objectKey})
	GetMedia(w http.ResponseWriter, r *http.Request, objectKey string)
	// ListNotifications List the current user's notifications with unread count
	// (GET /api/v1/notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// MarkNotificationsRead Mark selected or all notifications as read
	// (POST /api/v1/notifications/read)
	MarkNotificationsRead(w http.ResponseWriter, r *http.Request)
	// CreateReport Report a specific message in an accessible chat
	// (POST /api/v1/reports)
	CreateReport(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current session
	// (DELETE /api/v1/session)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetSession Get the current demo session
	// (GET /api/v1/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// Login Log in by phone and establish an opaque cookie session
	// (POST /api/v1/session)
	Login(w http.ResponseWriter, r *http.Request)
	// CreateUser Register a demo user and establish a session
	// (POST /api/v1/users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// GetUser Get a user profile
	// (GET /api/v1/users/{userId})
	GetUser(w http.ResponseWriter, r *http.Request, userId int64)
	// UpdateUser Update the current user's profile
	// (PATCH /api/v1/users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId int64)
	// ListUserItems List exchange items owned by a user
	// (GET /api/v1/users/{userId}/items)
	ListUserItems(w http.ResponseWriter, r *http.Request, userId int64, params ListUserItemsParams)
	// ListUserReviews List reviews received by a user
	// (GET /api/v1/users/{userId}/reviews)
	ListUserReviews(w http.ResponseWriter, r *http.Request, userId int64, params ListUserReviewsParams)
	// AnalyzePhoto Trigger async AI photo analysis
	// (POST /api/v1/vision/analyze)
	AnalyzePhoto(w http.ResponseWriter, r *http.Request)
	// GetLegacyHealth Check process liveness using the legacy path
	// (GET /health)
	//
	// Deprecated: this operation has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	GetLegacyHealth(w http.ResponseWriter, r *http.Request)
}

